// Compile-time proof that the FastAPI schema (schema.ts, generated by `npm run schema`)
// matches the API contract (types.ts, ask.types.ts). tsc fails on any differing field.
import type { components } from './schema';
import type * as T from './types';
import type * as A from './ask.types';

type S = components['schemas'];
type Same<X, Y> = [X] extends [Y] ? ([Y] extends [X] ? true : false) : false;
const same = <X, Y>(ok: Same<X, Y>) => ok;
// Request bodies: everything the UI sends must be accepted. (The API also accepts null for
// ReviewRequest's optional fields; the UI never sends it.)
const accepts = <Api, Ui>(ok: [Ui] extends [Api] ? true : false) => ok;

export const checks = [
  same<S['Summary'], T.Summary>(true),
  same<S['FindingRow'], T.FindingRow>(true),
  same<S['Finding'], T.Finding>(true),
  same<S['QuoteEvidence'], T.QuoteEvidence>(true),
  same<S['MissingEvidence'], T.MissingEvidence>(true),
  same<S['Citation'], T.Citation>(true),
  same<S['Fact'], T.Fact>(true),
  same<S['DateMark'], T.DateMark>(true),
  same<S['DateClash'], T.DateClash>(true),
  same<S['LongHorizonNote'], T.LongHorizonNote>(true),
  same<S['DocumentSummary'], T.DocumentSummary>(true),
  same<S['ExpectedDocument'], T.ExpectedDocument>(true),
  same<S['EvalStatus'], T.EvalStatus>(true),
  accepts<S['ReviewRequest'], T.ReviewRequest>(true),
  same<S['ReviewResponse'], T.ReviewResponse>(true),
  same<S['Rfi'], T.Rfi>(true),
  accepts<S['AskRequest'], A.AskRequest>(true),
  same<S['AskSentence'], A.AskSentence>(true),
  same<S['AskResponse'], A.AskResponse>(true),
  same<S['AskSuggestion'], A.AskSuggestion>(true),
];
